import { ReactNode } from 'react';

import { getTextWidth } from '../../../../../typography/utils.js';
import {
  HistogramAnnotation,
  isHistogramValueAnnotation,
} from '../../../types/histogram-annotations.js';
import { XScale } from '../../../types/histogram.js';
import { MARKER_PADDING, markerFontProps } from '../constants.js';

/**
 * Calculates the x-coordinate for a marker based on the annotation, scale, and width provided.
 * @param annotation - The annotation object that contains the value or range for the marker.
 * @param scale - The scale used to map the annotation value or range to the x-axis.
 * @param width - The width of the marker.
 * @returns The calculated x-coordinate for the marker.
 */
export const calculateMarkerCoordinate = (
  annotation: HistogramAnnotation,
  scale: XScale,
  width: number,
) => {
  if (isHistogramValueAnnotation(annotation)) {
    const x = Number(scale(annotation));
    return x - width / 2;
  }

  const x0 = Number(scale(annotation.from));
  const x1 = Number(scale(annotation.to));
  const xMiddle = (x0 + x1) / 2;
  return xMiddle - width / 2;
};

/**
 * Calculates the position of a marker on a chart grid based on its x-coordinate,
 * label width, and the available width of the grid.
 * @param x - The x-coordinate of the marker.
 * @param labelWidth - The width of the marker's label.
 * @param availableWidth - The available width of the chart grid.
 * @returns An object containing the adjusted x-coordinate and label width of the marker.
 */
export const handleMarkerPosition = (
  x: number,
  labelWidth: number,
  availableWidth: number,
) => {
  let markerX = x;
  let markerLabelWidth = labelWidth;
  if (x + labelWidth > availableWidth) {
    markerX = availableWidth - labelWidth;
    markerLabelWidth = availableWidth - markerX;
  } else if (x < 0) {
    markerX = 0;
  }

  if (labelWidth > availableWidth) {
    markerLabelWidth = availableWidth;
    markerX = 0;
  }

  return { x: markerX, labelWidth: markerLabelWidth };
};

/**
 * Calculates the marker width that should be assigned considering scale
 * and available width
 *
 * @param title - The title of the marker
 * @param value - The value of the marker
 * @param scale - The scale used for the annotations
 * @param availableWidth - The width available in annotations area
 * @returns The width in pixels for the marker
 */
export const getMarkerWidth = (
  title: string,
  value: HistogramAnnotation,
  scale: XScale,
  availableWidth: number,
  symbol?: string | ReactNode,
) => {
  const titleWidth = getTextWidth(title, markerFontProps);

  if (isHistogramValueAnnotation(value)) {
    return title.length > 2 && !symbol ? titleWidth : 0;
  }

  const minDomainRange = Number(scale(scale.domain()[0]));
  const xTo = Number(scale(value.to));
  const xFrom = Number(scale(value.from));

  let finalTo = xTo;
  let finalFrom = xFrom;

  if (xFrom < 0 || isNaN(xFrom)) {
    finalFrom = minDomainRange;
  } else if (xTo > availableWidth) {
    finalTo = availableWidth;
  }

  const rangeIndicator = finalTo - finalFrom - MARKER_PADDING;

  return Math.max(rangeIndicator, titleWidth) + MARKER_PADDING;
};

/**
 * Determines if a marker is completely out of bounds, meaning that
 * its width is totally outside of the border of the annotations area
 *
 */
export const isAnnotationTotallyOutOfBounds = (
  value: HistogramAnnotation,
  scale: XScale,
) => {
  const minDomainRange = Number(scale(scale.domain()[0]));
  const maxDomainRange = Number(scale(scale.domain()[1]));

  if (isHistogramValueAnnotation(value)) {
    const x = Number(scale(value));

    if (x < minDomainRange || x > maxDomainRange || isNaN(x)) {
      return true;
    }
  } else {
    const x0 = Number(scale(value.from));
    const x1 = Number(scale(value.to));
    if (
      x1 < minDomainRange ||
      x0 > maxDomainRange ||
      (isNaN(x0) && isNaN(x1))
    ) {
      return true;
    }
  }
  return false;
};
